#!/usr/bin/env python3
"""A filesystem usage tree, implemented from its command-line behavior."""

import errno
import os
import re
import stat
import sys
import unicodedata
from dataclasses import dataclass, field


OPTIONS = (
    ('d', 'depth', 'optional'),
    ('a', 'aggr', 'optional'),
    ('s', 'summary', 'flag'),
    ('u', 'usage', 'flag'),
    ('b', 'bytes', 'flag'),
    ('f', 'files-only', 'flag'),
    ('x', 'exclude', 'multiple'),
    ('H', 'no-hidden', 'flag'),
    ('A', 'ascii', 'flag'),
    ('h', 'help', 'flag'),
    ('v', 'version', 'flag'),
)
ALIASES = {name: (long, kind) for short, long, kind in OPTIONS
           for name in (short, long)}
MAX_U64 = (1 << 64) - 1


def help_text(program):
    return f"""Usage: {program} [options] <path> [<path>..]

Options:
    -d, --depth [DEPTH] show directories up to depth N (def 1)
    -a, --aggr [N[KMG]] aggregate smaller than N B/KiB/MiB/GiB (def 1M)
    -s, --summary       equivalent to -da, or -d1 -a1M
    -u, --usage         report real disk usage instead of file size
    -b, --bytes         print sizes in bytes
    -f, --files-only    skip directories for a fast local overview
    -x, --exclude NAME  exclude matching files or directories
    -H, --no-hidden     exclude hidden files
    -A, --ascii         ASCII characters only, no colors
    -h, --help          show help
    -v, --version       print version number
"""


class OptionError(Exception):
    pass


class ExitError(Exception):
    def __init__(self, message, status=1):
        super().__init__(message)
        self.status = status


def panic(location, message):
    raise ExitError(
        f"\nthread 'main' ({os.getpid()}) panicked at {location}:\n"
        f"{message}\n"
        "note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace",
        101,
    )


def parse_options(args):
    """Parse flags, including optional arguments and short option clusters."""
    values = {}
    paths = []
    index = 0
    while index < len(args):
        arg = args[index]
        index += 1
        if arg == '--':
            paths.extend(args[index:])
            break
        if len(arg) < 2 or not arg.startswith('-'):
            paths.append(arg)
            continue
        if arg.startswith('--'):
            token = arg[2:]
            name, sep, attached = token.partition('=')
            names = [(name, attached if sep else None, True)]
        else:
            names = None
            token = arg[1:]
        offset = 0
        while names or (names is None and offset < len(token)):
            if names:
                name, attached, long_form = names.pop()
            else:
                name, attached, long_form = token[offset], None, False
                offset += 1
            if name not in ALIASES:
                raise OptionError(f"Unrecognized option: '{name}'")
            canonical, kind = ALIASES[name]
            if kind == 'flag':
                if attached is not None:
                    raise OptionError(f"Option '{name}' does not take an argument")
                value = None
            else:
                if not long_form and offset < len(token):
                    attached = token[offset:]
                    offset = len(token)
                if attached is not None:
                    value = attached
                elif index < len(args) and (kind == 'multiple' or
                                           not (args[index].startswith('-') and
                                                len(args[index]) > 1)):
                    value = args[index]
                    index += 1
                elif kind == 'multiple':
                    raise OptionError(f"Argument to option '{name}' missing")
                else:
                    value = None
            values.setdefault(canonical, []).append(value)
            if long_form:
                break
    for short, long_name, kind in OPTIONS:
        if kind != 'multiple' and len(values.get(long_name, [])) > 1:
            raise OptionError(f"Option '{long_name}' given more than once")
    return values, paths


def parse_depth(value):
    if value is not None and re.fullmatch(r'\+?[0-9]+', value):
        n = int(value)
        if n <= MAX_U64:
            return n
    return 1


def parse_aggregation(value):
    if value is None:
        return 1024 * 1024
    match = re.fullmatch(r'(\d+)([^\d]?)', value, re.DOTALL)
    if not match:
        raise ExitError(f"invalid argument '{value}'")
    number, suffix = match.groups()
    if not number.isascii():
        panic('src/lib.rs:175:56',
              'called `Result::unwrap()` on an `Err` value: ParseIntError { kind: InvalidDigit }')
    n = int(number)
    if n > MAX_U64:
        panic('src/lib.rs:175:56',
              'called `Result::unwrap()` on an `Err` value: ParseIntError { kind: PosOverflow }')
    power = {'K': 1, 'M': 2, 'G': 3, 'T': 4}.get(suffix.upper(), 0)
    return (n * (1024 ** power)) & MAX_U64


def safe_name(path):
    name = os.path.basename(path.rstrip('/')) or '/'
    if any(0xDC80 <= ord(c) <= 0xDCFF for c in name):
        return '[invalid name]'
    return name


def error_kind(error):
    return {
        errno.EACCES: 'PermissionDenied',
        errno.EPERM: 'PermissionDenied',
        errno.ENOENT: 'NotFound',
        errno.ENOTDIR: 'NotADirectory',
        errno.ELOOP: 'FilesystemLoop',
        errno.EINVAL: 'InvalidInput',
        errno.EINTR: 'Interrupted',
        errno.ENOMEM: 'OutOfMemory',
    }.get(error.errno, 'Uncategorized')


def read_error(name, kind):
    sys.stderr.write(f"Couldn't read {name} ({kind})\n")


@dataclass
class Node:
    name: str
    size: int = 0
    path: str = None
    mode: int = 0
    directory: bool = False
    children: list = field(default_factory=list)
    read_failure: str = None


@dataclass
class Settings:
    depth: int = MAX_U64
    aggregate: int = 0
    disk_usage: bool = False
    byte_sizes: bool = False
    files_only: bool = False
    no_hidden: bool = False
    ascii: bool = False
    excludes: set = field(default_factory=set)


def scan(path, settings):
    """Collect sizes without following symlinks or deduplicating hard links."""
    name = safe_name(path)
    try:
        metadata = os.lstat(path)
    except OSError as error:
        read_error(name, error_kind(error))
        return Node(name, path=path)
    directory = stat.S_ISDIR(metadata.st_mode)
    if directory:
        name = safe_name(os.path.realpath(path))
    node = Node(name, (metadata.st_blocks * 512 if settings.disk_usage
                       else metadata.st_size), path, metadata.st_mode, directory)
    if not directory:
        return node
    try:
        with os.scandir(path) as entries:
            for entry in entries:
                entry_name = safe_name(entry.path)
                if entry_name in settings.excludes:
                    continue
                if settings.no_hidden and entry_name.startswith('.'):
                    continue
                if settings.files_only:
                    try:
                        if entry.is_dir(follow_symlinks=True):
                            continue
                    except OSError:
                        pass
                child = scan(entry.path, settings)
                node.children.append(child)
                node.size = (node.size + child.size) & MAX_U64
    except OSError as error:
        node.read_failure = error_kind(error)
        read_error(name, node.read_failure)
    return node


def arrange(node, settings, depth=0):
    """Apply the display depth and coalesce small entries at each directory."""
    if depth >= settings.depth:
        node.children = []
        return
    if node.read_failure:
        read_error(node.name, node.read_failure)
    for child in node.children:
        arrange(child, settings, depth + 1)
    node.children.sort(key=lambda n: -n.size)
    if settings.aggregate:
        kept = []
        aggregate = 0
        for child in node.children:
            if child.size < settings.aggregate:
                aggregate = (aggregate + child.size) & MAX_U64
            else:
                kept.append(child)
        if aggregate:
            kept.append(Node('<aggregated>', aggregate))
        node.children = kept


def character_width(character):
    code = ord(character)
    category = unicodedata.category(character)
    if code == 0 or code < 32 or 0x7F <= code < 0xA0:
        return 0
    if category in ('Mn', 'Me', 'Cf'):
        return 0
    return 2 if unicodedata.east_asian_width(character) in ('W', 'F') else 1


def trim_name(name, width):
    out = []
    used = 0
    for character in name:
        advance = character_width(character)
        if used + advance > width:
            break
        out.append(character)
        used += advance
    return ''.join(out), used


def format_size(number, byte_sizes):
    if byte_sizes or number < 1024:
        return f'{number} B'
    units = ['KiB', 'MiB', 'GiB', 'TiB', 'PiB', 'EiB']
    exponent = 1
    while exponent < len(units) and number >= 1024 ** (exponent + 1):
        exponent += 1
    return f'{number / (1024 ** exponent):.2f} {units[exponent - 1]}'


class Palette:
    def __init__(self, specification):
        self.colors = {}
        self.extensions = {}
        for pair in specification.split(':'):
            if not pair:
                break
            parts = pair.split('=')
            if len(parts) < 2:
                panic('src/lib.rs:565:36', 'called `Option::unwrap()` on a `None` value')
            key, value = parts[:2]
            key_bytes = key.encode('utf-8', 'replace')
            if len(key_bytes) < 2:
                panic('src/lib.rs:530:20', f'byte index 2 is out of bounds of `{key}`')
            if key.startswith('*.'):
                self.extensions[key[2:]] = value
            else:
                self.colors[key] = value

    def color(self, node):
        if not node.path:
            return None
        colors = self.colors
        if stat.S_ISLNK(node.mode) and 'or' in colors:
            return colors['or']
        if 'di' in colors and os.path.isdir(node.path):
            return colors['di']
        if node.mode & 0o111 and 'ex' in colors:
            return colors['ex']
        if '.' in node.name[1:]:
            extension = node.name.rsplit('.', 1)[1]
            if extension in self.extensions:
                return self.extensions[extension]
        return colors.get('fi' if os.path.isfile(node.path) else 'bd')


class Renderer:
    def __init__(self, settings, palette):
        self.settings = settings
        self.palette = palette
        try:
            self.width = os.get_terminal_size(sys.stdout.fileno()).columns
        except OSError:
            self.width = 80
        self.name_width = max(25, (self.width - 15) // 4)
        self.bar_width = self.width - self.name_width - 22
        self.lines = []

    def render(self, root):
        self.lines.append(f'[ {root.name} {format_size(root.size, self.settings.byte_sizes)} ]\n')
        maximum = max((node.size for node in root.children), default=0)
        if root.children:
            self.rows(root, '', self.bar_width, maximum, [], 1)
        return ''.join(self.lines)

    def rows(self, parent, prefix, parent_scale, denominator, ancestors, depth):
        if len(prefix) + 3 >= self.name_width:
            return
        for index, node in enumerate(parent.children):
            last = index == len(parent.children) - 1
            branch = '└─ ' if last else '├─ '
            available = self.name_width - len(prefix) - 3
            name, used = trim_name(node.name, available)
            color = None if self.settings.ascii else self.palette.color(node)
            painted = f'\x1b[{color}m{name}\x1b[0m' if color is not None else name
            scale = int(parent_scale * (node.size / denominator)) if denominator else 0
            fill = max(0, scale - 1)
            cells = [' '] * self.bar_width
            for level, ancestor_scale in enumerate(ancestors):
                shade = '#' if self.settings.ascii else '░▒▓█'[min(level, 3)]
                start = max(0, self.bar_width - max(0, ancestor_scale - 1))
                cells[start:] = [shade] * (self.bar_width - start)
            foreground = '#' if self.settings.ascii else '█'
            start = max(0, self.bar_width - fill)
            cells[start:] = [foreground] * (self.bar_width - start)
            percent = int(100.0 * (node.size / parent.size)) if parent.size else 0
            size = format_size(node.size, self.settings.byte_sizes)
            self.lines.append(prefix + branch + painted + ' ' * (available - used) +
                              ' │' + ''.join(cells) + f'│{percent:4d}%{size:>14}\n')
            next_prefix = prefix + ('   ' if last else '│  ')
            self.rows(node, next_prefix, scale, node.size, ancestors + [scale], depth + 1)


def main():
    try:
        options, paths = parse_options(sys.argv[1:])
    except OptionError as error:
        sys.stderr.write(str(error) + '\n')
        sys.stdout.write(help_text(sys.argv[0]))
        return 1
    if 'help' in options:
        sys.stdout.write(help_text(sys.argv[0]))
        return 0
    if 'version' in options:
        sys.stdout.write('dutree version 0.2.18\n')
        return 0
    palette = Palette(os.environ.get('LS_COLORS', ''))
    if not paths:
        paths = [os.getcwd()]
    for path in paths:
        if not os.path.exists(path):
            raise ExitError(f"path {path} doesn't exist")
    settings = Settings(
        disk_usage='usage' in options,
        byte_sizes='bytes' in options,
        files_only='files-only' in options,
        no_hidden='no-hidden' in options,
        ascii='ascii' in options,
        excludes=set(options.get('exclude', [])),
    )
    if 'depth' in options:
        settings.depth = parse_depth(options['depth'][0])
    if 'aggr' in options:
        settings.aggregate = parse_aggregation(options['aggr'][0])
    if 'summary' in options:
        settings.depth = 1
        settings.aggregate = 1024 * 1024
    roots = [scan(path, settings) for path in paths]
    for root in roots:
        arrange(root, settings)
    if len(roots) == 1:
        root = roots[0]
    else:
        root = Node('<collection>', sum(n.size for n in roots) & MAX_U64,
                    children=sorted(roots, key=lambda n: -n.size))
    sys.stdout.write(Renderer(settings, palette).render(root))
    return 0


if __name__ == '__main__':
    sys.setrecursionlimit(10000)
    try:
        result = main()
    except ExitError as error:
        sys.stderr.write(str(error) + '\n')
        result = error.status
    except BrokenPipeError:
        result = 0
        try:
            sys.stdout = open(os.devnull, 'w')
        except OSError:
            pass
    sys.exit(result)
PY
